<?php

const MOD = 998244353;

function modinv($a) {
    return pow($a, MOD - 2, MOD);
}

function main() {
    $input = trim(file_get_contents("php://stdin"));
    list($n, $k, $l) = array_map('intval', explode(' ', $input));

    if ($n == 0) {
        echo 0;
        return;
    }

    // Precompute factorials and inverse factorials up to n
    $fact = array_fill(0, $n + 1, 1);
    for ($i = 1; $i <= $n; ++$i) {
        $fact[$i] = $fact[$i - 1] * $i % MOD;
    }

    $inv_fact = array_fill(0, $n + 1, 1);
    $inv_fact[$n] = modinv($fact[$n]);
    for ($i = $n - 1; $i >= 0; --$i) {
        $inv_fact[$i] = $inv_fact[$i + 1] * ($i + 1) % MOD;
    }

    // Precompute powers of 2 mod MOD
    $pow2 = array_fill(0, $n + 1, 1);
    for ($i = 1; $i <= $n; ++$i) {
        $pow2[$i] = $pow2[$i - 1] * 2 % MOD;
    }

    // DP table: dp[i][j] represents the probability of having j segments covering up to the i-th segment
    $dp = array_fill(0, $n + 1, array_fill(0, $n + 1, 0));
    $dp[0][0] = 1;

    for ($i = 0; $i < $n; ++$i) {
        for ($j = 0; $j <= $i; ++$j) {
            if ($dp[$i][$j] == 0) continue;
            // The next segment does not cover the point
            $dp[$i + 1][$j] = ($dp[$i + 1][$j] + $dp[$i][$j] * ($pow2[$n - 1 - $i] % MOD)) % MOD;
            // The next segment covers the point
            if ($j + 1 <= $n) {
                $dp[$i + 1][$j + 1] = ($dp[$i + 1][$j + 1] + $dp[$i][$j] * ($pow2[$i] % MOD)) % MOD;
            }
        }
    }

    // Sum probabilities for j >= k
    $prob = 0;
    for ($j = $k; $j <= $n; ++$j) {
        $prob = ($prob + $dp[$n][$j]) % MOD;
    }

    // The integral over [0, 1] of the probability is prob / (2^n)
    // But since we used DP with powers of 2, we need to adjust
    // The DP already accounts for the binomial coefficients, so the integral is prob * inv(2^n)
    $inv_2n = modinv(pow(2, $n, MOD));
    $result = $prob * $inv_2n % MOD;

    // Multiply by l and take modulo
    $result = $result * $l % MOD;

    echo $result;
