<?php

const MOD = 998244353;

function modinv($a, $mod = MOD) {
    return pow($a, $mod - 2, $mod);
}

function main() {
    $input = trim(file_get_contents("php://stdin"));
    list($n, $k, $l) = array_map('intval', explode(' ', $input));

    // Precompute factorial and inverse factorial up to 2n
    $max_n = 2 * $n;
    $fact = array_fill(0, $max_n + 1, 1);
    for ($i = 1; $i <= $max_n; $i++) {
        $fact[$i] = $fact[$i - 1] * $i % MOD;
    }
    $inv_fact = array_fill(0, $max_n + 1, 1);
    $inv_fact[$max_n] = modinv($fact[$max_n]);
    for ($i = $max_n - 1; $i >= 0; $i--) {
        $inv_fact[$i] = $inv_fact[$i + 1] * ($i + 1) % MOD;
    }

    // Precompute powers of 2 inverse
    $inv2 = modinv(2);
    $pow2_inv = array_fill(0, $n + 1, 1);
    for ($i = 1; $i <= $n; $i++) {
        $pow2_inv[$i] = $pow2_inv[$i - 1] * $inv2 % MOD;
    }

    // Precompute binomial coefficients C(n, m)
    $C = array_fill(0, $n + 1, array_fill(0, $n + 1, 0));
    for ($i = 0; $i <= $n; $i++) {
        $C[$i][0] = 1;
        for ($j = 1; $j <= $i; $j++) {
            $C[$i][$j] = ($C[$i - 1][$j - 1] + $C[$i - 1][$j]) % MOD;
        }
    }

    // Compute the integral part
    $res = 0;
    for ($m = $k; $m <= $n; $m++) {
        $term = $C[$n][$m] * $pow2_inv[$m] % MOD;
        $term = $term * (1 - $pow2_inv[$n - $m + 1] + MOD) % MOD;
        $res = ($res + $term) % MOD;
    }

    // Multiply by l and divide by 2n+1
    $denominator = (2 * $n + 1) % MOD;
    $inv_denominator = modinv($denominator);
    $ans = $l % MOD * $res % MOD;
    $ans = $ans * $inv_denominator % MOD;

    echo $ans . "\n";
}

main();
