<?php
const MOD = 998244353;

function modinv($a) {
    return pow($a, MOD-2, MOD);
}

function precompute_factorials($n) {
    $fact = array_fill(0, $n+1, 1);
    $inv_fact = array_fill(0, $n+1, 1);
    for ($i = 1; $i <= $n; $i++) {
        $fact[$i] = $fact[$i-1] * $i % MOD;
    }
    $inv_fact[$n] = modinv($fact[$n]);
    for ($i = $n-1; $i >= 0; $i--) {
        $inv_fact[$i] = $inv_fact[$i+1] * ($i+1) % MOD;
    }
    return [$fact, $inv_fact];
}

function comb($n, $k, $fact, $inv_fact) {
    if ($k < 0 || $k > $n) return 0;
    return $fact[$n] * $inv_fact[$k] % MOD * $inv_fact[$n - $k] % MOD;
}

list($fact, $inv_fact) = precompute_factorials(4000);

$line = trim(fgets(STDIN));
list($n, $k, $l) = array_map('intval', explode(' ', $line));

$ans = 0;
for ($i = 0; $i <= $n; $i++) {
    for ($j = 0; $j <= $n; $j++) {
        if ($i + $j < $k) continue;
        $c = comb($n, $i, $fact, $inv_fact) * comb($n, $j, $fact, $inv_fact) % MOD;
        $c = $c * modinv($i + $j + 1) % MOD;
        $c = $c * ($i + $j >= $k ? 1 : 0) % MOD;
        $ans = ($ans + $c) % MOD;
    }
}
$ans = $ans * $l % MOD;
echo $ans . "\n";
